# Rebuild exact local Witch's Cottage V1 using Python stdlib only.
import base64,gzip,hashlib,runpy
from pathlib import Path
here=Path(__file__).resolve().parent
source=gzip.decompress(base64.b64decode("""""",validate=True))
assert hashlib.sha256(source).hexdigest()=="89060f011652266b0828cc2f4a720b0dc74e5f9146e8d6d6c84b211bc165b2b7"
script=here/"build_cottage.py"
if script.exists() and script.read_bytes()!=source: raise RuntimeError("Preserve manually edited source before replay")
script.write_bytes(source)
runpy.run_path(str(script),run_name="__main__")
assert hashlib.sha256(gzip.decompress((here/"prefab-extension/witch_cottage.nbt").read_bytes())).hexdigest()=="22684de43d78e78749082ee4bfa899db3682bab8d24626976060b88c34eacfb9"
